import React from "react";
import Sort from "@/components/Sort";
import { getFiles } from "@/lib/actions/file.actions";
import { Models } from "node-appwrite";
import Card from "@/components/Card";
import { getFileTypesParams } from "@/lib/utils";
import CreateFolder from "@/components/CreateFolder";
import FolderList from "@/components/FolderList";

const Page = async ({ searchParams, params }: SearchParamProps) => {
  const type = ((await params)?.type as string) || "";
  const searchText = ((await searchParams)?.query as string) || "";
  const sort = ((await searchParams)?.sort as string) || "";
  const folderId = ((await searchParams)?.folderId as string) || undefined;

  const types = getFileTypesParams(type) as FileType[];

  const files = await getFiles({ types, searchText, sort, folderId });

  return (
    <div className="page-container">
      <section className="w-full">
        <h1 className="h1 capitalize">{type}</h1>

        <div className="total-size-section">
          <p className="body-1">
            Total: <span className="h5">{(files.documents.reduce((acc: number, file: Models.Document) => acc + (file.size || 0), 0) / (1024 * 1024)).toFixed(2)} MB</span>
          </p>

          <div className="sort-container">
            <p className="body-1 hidden text-light-200 sm:block">Sort by:</p>

            <Sort />
          </div>
        </div>
      </section>

      {/* Folder List */}
      <section>
        <h2 className="h3 mb-4">Folders</h2>
        <FolderList parentId={folderId} />
      </section>
      
      {/* Create Folder Button */}
      <CreateFolderButton parentId={folderId} />

      {/* Render the files */}
      <section className="mt-8">
        <h2 className="h3 mb-4">Files</h2>
        {files.total > 0 ? (
          <div className="file-list">
            {files.documents.map((file: Models.Document) => (
              <Card key={file.$id} file={file} />
            ))}
          </div>
        ) : (
          <p className="empty-list">No files uploaded</p>
        )}
      </section>
    </div>
  );
};

export default Page;
